def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build the grid, initialize with zeros
    grid = [[0] * N for _ in range(N)]

    # Parse the grid values, stop at the all-zero terminator
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 0 <= x < N and 0 <= y < N:
            grid[x][y] = val

    # Edge case: if N is 0 or 1, handle trivially
    if N <= 0:
        return 0
    if N == 1:
        return grid[0][0]

    # DP state: dp[step][r1][r2] where step is the diagonal step (from 0 to 2N-2)
    # At step k, we are on the diagonal where i + j = k
    # Each path has row index r1 and r2, and column is j = k - r1
    # We want to maximize the sum of values collected by two paths.

    # Use negative infinity to represent unreachable states
    neg_inf = float('-inf')

    # Initialize DP table: dp[step][r1][r2]
    # step ranges from 0 to 2N-2
    # r1 and r2 range from 0 to N-1, but constrained by the diagonal
    dp = [[[neg_inf] * N for _ in range(N)] for _ in range(2 * N)]

    # Start at top-left: step 0, r1=0, r2=0
    dp[0][0][0] = grid[0][0]

    for step in range(1, 2 * N):
        for r1 in range(N):
            c1 = step - r1
            if c1 < 0 or c1 >= N:
                continue
            for r2 in range(N):
                c2 = step - r2
                if c2 < 0 or c2 >= N:
                    continue

                # The previous step is step-1
                # Previous positions for path1: (r1, c1-1) or (r1-1, c1) -> in terms of rows: r1 or r1-1 at step-1
                # Similarly for path2: r2 or r2-1
                # So we consider all 4 combinations of previous row positions
                best_prev = neg_inf
                for pr1 in (r1 - 1, r1):
                    if pr1 < 0:
                        continue
                    prev_c1 = (step - 1) - pr1
                    if prev_c1 < 0 or prev_c1 >= N:
                        continue
                    for pr2 in (r2 - 1, r2):
                        if pr2 < 0:
                            continue
                        prev_c2 = (step - 1) - pr2
                        if prev_c2 < 0 or prev_c2 >= N:
                            continue
                        if dp[step - 1][pr1][pr2] > best_prev:
                            best_prev = dp[step - 1][pr1][pr2]

                if best_prev == neg_inf:
                    continue

                # Add current cell values
                add_val = grid[r1][c1]
                if r1 != r2 or c1 != c2:
                    add_val += grid[r2][c2]
                # If both paths are on the same cell, count only once

                dp[step][r1][r2] = best_prev + add_val

    # The answer is at step = 2*N - 2, r1 = N-1, r2 = N-1
    result = dp[2 * N - 2][N - 1][N - 1]
    if result == neg_inf:
        return 0
    return result

