def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 1D DP array of size n+1, where dp[j] represents the max importance with budget j
    dp = [0] * (n + 1)

    for i in range(m):
        price = items[i][0]
        value = items[i][1]
        # Traverse from n down to price to avoid reusing the same item
        for j in range(n, price - 1, -1):
            if dp[j - price] + value > dp[j]:
                dp[j] = dp[j - price] + value

    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0:
        raise ValueError("Highest degree n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = ''
        abs_coeff = abs(coeff)

        # Determine the sign part, excluding a leading '+' for the first term
        if coeff < 0:
            sign = '-'
        elif sign == '' and terms:  # if there are already terms and coeff is positive
            sign = '+'

        # Determine the coefficient part
        if degree > 0:
            if abs_coeff == 1:
                coeff_part = ''
            else:
                coeff_part = str(abs_coeff)
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)

