def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0
    quotient = y0 // x0
    count = 0
    i = 1
    while i * i <= quotient:
        if quotient % i == 0:
            a = i
            b = quotient // i
            if __import__('math').gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    in_pos = {ch: idx for idx, ch in enumerate(inorder)}
    result = []

    def build(in_left, in_right, post_left, post_right):
        if in_left > in_right or post_left > post_right:
            return
        root = postorder[post_right]
        result.append(root)
        root_in_idx = in_pos[root]

        left_subtree_len = root_in_idx - in_left
        build(in_left, root_in_idx - 1, post_left, post_left + left_subtree_len - 1)
        build(root_in_idx + 1, in_right, post_left + left_subtree_len, post_right - 1)

    n = len(inorder)
    if n == 0:
        return ""
    build(0, n - 1, 0, n - 1)
    return ''.join(result)

