        return 1

    start = str(n)
    visited = set([start])
    queue = [start]

    # Build a dictionary of rules for quick lookup
    rule_map = {}
    for x, y in rules:
        if str(x) not in rule_map:
            rule_map[str(x)] = set()
        rule_map[str(x)].add(str(y))

    while queue:
        current = queue.pop(0)
        for i in range(len(current)):
            digit = current[i]
            if digit in rule_map:
