        elif point == 'L':
            opponent_score += 1
        else:
            continue

        player_wins = player_score >= system and (player_score - opponent_score) >= 2
        opponent_wins = opponent_score >= system and (opponent_score - player_score) >= 2

        if player_wins or opponent_wins:
