def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    if n <= 1:
        return 0

    # Calculate Longest Increasing Subsequence ending at each index (LIS)
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate Longest Decreasing Subsequence starting at each index (LDS)
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum formation length
    max_formation = 0
    for i in range(n):
        max_formation = max(max_formation, lis[i] + lds[i] - 1)

    return n - max_formation

